const seen = new Set();
const config = $('Set Configuration').first().json;

const filtered = items.filter(item => {
  const repo = item.json;
  if (seen.has(repo.full_name)) return false;
  seen.add(repo.full_name);

  if (!config.include_archived && repo.archived) return false;
  if (!config.include_forks && repo.fork) return false;

  return true;
});

return filtered;

const PLATFORMS = {
  'vercel.app': 'Vercel', 'netlify.app': 'Netlify', 'repl.co': 'Replit',
  'pages.dev': 'Cloudflare', 'supabase': 'Supabase', 'base44': 'Base44', 'bolt': 'Bolt'
};

const CATEGORIES = {
  'mcp': 'MCP Server', 'automation': 'Automation', 'docs': 'Documentation',
  'template': 'Template', 'infrastructure': 'Infrastructure', 'client': 'Client Work'
};

return items.map(item => {
  const r = item.json;
  const topics = r.topics || [];
  const homepage = (r.homepage || '').toLowerCase();
  const name = r.name.toLowerCase();

  // Detect platform
  let platform = 'GitHub';
  for (const [key, val] of Object.entries(PLATFORMS)) {
    if (homepage.includes(key) || topics.includes(key) || name.includes(key)) {
      platform = val; break;
    }
  }

  // Detect category
  let category = 'Internal Tool';
  for (const [key, val] of Object.entries(CATEGORIES)) {
    if (topics.includes(key) || name.includes(key)) {
      category = val; break;
    }
  }

  // Detect status
  const daysSincePush = Math.floor((Date.now() - new Date(r.pushed_at)) / 86400000);
  let status = 'Active';
  if (r.archived) status = 'Archived';
  else if (daysSincePush > 365) status = 'Sunset';
  else if (daysSincePush > 180) status = 'Paused';

  // Calculate metrics
  const stars = r.stargazers_count || 0;
  const issues = r.open_issues_count || 0;

  let priority = 3, businessValue = 3, techDebt = 2, complexity = 3;
  if (stars > 10) businessValue = 4;
  if (stars > 50) businessValue = 5;
  if (issues > 10) techDebt = 3;
  if (issues > 25) techDebt = 4;
  if (daysSincePush < 7) priority = 5;
  else if (daysSincePush < 30) priority = 4;
  else if (daysSincePush > 180) priority = 2;
  if (r.size > 50000) complexity = 4;

  return {
    json: {
      id: `gh-${r.id}`,
      name: r.name,
      platform,
      category,
      status,
      lastActivity: r.pushed_at?.split('T')[0] || '',
      owner: r.owner.login,
      priority,
      complexity,
      businessValue,
      techDebt,
      notes: r.description || '',
      repo: r.html_url,
      monthlyCost: 0,
      migrationTarget: (platform === 'Base44' || platform === 'Bolt') ? '' : null,
      migrationStatus: '',
      auditChecks: {},
      dependsOn: [],
      githubData: {
        stars: r.stargazers_count,
        forks: r.forks_count,
        openIssues: r.open_issues_count,
        language: r.language,
        size: r.size,
        topics: r.topics,
        isPrivate: r.private,
        defaultBranch: r.default_branch
      }
    }
  };
});

// Check for README, LICENSE, CI files via GitHub API
const results = [];

for (const item of items) {
  const p = item.json;
  if (!p.repo?.includes('github.com')) {
    results.push(item);
    continue;
  }

  const match = p.repo.match(/github\.com\/([^\/]+)\/([^\/]+)/);
  if (!match) { results.push(item); continue; }

  const [, owner, repo] = match;
  const repoName = repo.replace('.git', '');

  try {
    // Fetch root contents
    const contentsRes = await this.helpers.httpRequest({
      url: `https://api.github.com/repos/${owner}/${repoName}/contents`,
      headers: { 'Authorization': `token ${$credentials.githubApi.accessToken}` }
    });

    const files = contentsRes.map(f => f.name.toLowerCase());
    const dirs = contentsRes.filter(f => f.type === 'dir').map(f => f.name.toLowerCase());

    p.auditChecks = {
      readme: files.some(f => f.startsWith('readme')),
      license: files.some(f => f.startsWith('license')),
      contributing: files.some(f => f.startsWith('contributing')),
      tests: ['test', 'tests', '__tests__', 'spec'].some(d => dirs.includes(d)) ||
             files.some(f => f.includes('.test.') || f.includes('.spec.')),
      ci: dirs.includes('.github') || files.includes('.gitlab-ci.yml'),
      security: files.includes('security.md'),
      secrets: true,
      rls: dirs.includes('supabase'),
      soc2: false,
      hipaa: false,
      gdpr: false
    };
  } catch (e) {
    p.auditChecks = {};
  }

  results.push({ json: p });

  // Rate limit
  await new Promise(r => setTimeout(r, 100));
}

return results;

const COSTS = {
  'Vercel': 20, 'Netlify': 19, 'Replit': 20, 'Supabase': 25,
  'GCP': 50, 'AWS': 75, 'Cloudflare': 5, 'GitHub': 0,
  'Loveable': 0, 'Base44': 0, 'Bolt': 0
};

return items.map(item => {
  const p = item.json;
  if (!p.monthlyCost && COSTS[p.platform] !== undefined) {
    p.monthlyCost = COSTS[p.platform];
    p._costSource = 'platform-default';
  }
  return { json: p };
});

return items.map(item => {
  const p = item.json;
  const days = p.lastActivity ? Math.floor((Date.now() - new Date(p.lastActivity)) / 86400000) : 999;

  let score = 100;
  if (days > 180) score -= 40;
  else if (days > 90) score -= 25;
  else if (days > 30) score -= 10;

  score -= ((p.techDebt || 3) - 1) * 8;
  if (p.status === 'Blocked') score -= 20;
  if (p.status === 'Archived' || p.status === 'Sunset') score -= 30;
  score += ((p.businessValue || 3) - 3) * 5;

  const auditPassed = Object.values(p.auditChecks || {}).filter(Boolean).length;
  score += auditPassed * 2;

  p.health = Math.max(0, Math.min(100, Math.round(score)));

  return { json: p };
});

const projects = items[0].json.projects;

const summary = {
  runId: $('Set Configuration').first().json.run_id,
  timestamp: new Date().toISOString(),
  total: projects.length,
  byStatus: {},
  byPlatform: {},
  needsMigration: 0,
  unhealthy: 0,
  totalMonthlyCost: 0,
  avgHealth: 0,
  auditCompletion: 0,
  alerts: []
};

let healthSum = 0, auditSum = 0;

for (const p of projects) {
  summary.byStatus[p.status] = (summary.byStatus[p.status] || 0) + 1;
  summary.byPlatform[p.platform] = (summary.byPlatform[p.platform] || 0) + 1;
  summary.totalMonthlyCost += p.monthlyCost || 0;
  healthSum += p.health || 0;

  const auditPassed = Object.values(p.auditChecks || {}).filter(Boolean).length;
  auditSum += auditPassed / 11 * 100;

  if (p.platform === 'Base44' || p.platform === 'Bolt') summary.needsMigration++;
  if (p.health < 40) summary.unhealthy++;

  // Generate alerts
  if (p.health < 30 && p.priority >= 4) {
    summary.alerts.push({ type: 'critical', project: p.name, message: `High-priority project with critical health (${p.health})` });
  }
  if ((p.platform === 'Base44' || p.platform === 'Bolt') && !p.migrationTarget) {
    summary.alerts.push({ type: 'migration', project: p.name, message: `Needs migration target (${p.platform} sunset)` });
  }
}

summary.avgHealth = Math.round(healthSum / projects.length);
summary.auditCompletion = Math.round(auditSum / projects.length);

return [{ json: { summary, projects } }];

const { summary, projects } = items[0].json;
const dbId = $('Set Configuration').first().json.notion_database_id;

if (!dbId) {
  return [{ json: { skipped: true, reason: 'No Notion database configured' } }];
}

const results = [];

for (const p of projects.slice(0, 100)) { // Limit for rate limiting
  try {
    // Search for existing page
    const searchRes = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.notion.com/v1/databases/' + dbId + '/query',
      headers: {
        'Authorization': `Bearer ${$credentials.notionApi.apiKey}`,
        'Notion-Version': '2022-06-28',
        'Content-Type': 'application/json'
      },
      body: {
        filter: { property: 'GitHub ID', rich_text: { equals: p.id } }
      }
    });

    const properties = {
      'Name': { title: [{ text: { content: p.name } }] },
      'GitHub ID': { rich_text: [{ text: { content: p.id } }] },
      'Platform': { select: { name: p.platform } },
      'Status': { select: { name: p.status } },
      'Category': { select: { name: p.category } },
      'Health': { number: p.health },
      'Priority': { number: p.priority },
      'Monthly Cost': { number: p.monthlyCost || 0 },
      'Last Activity': p.lastActivity ? { date: { start: p.lastActivity } } : { date: null },
      'Owner': { rich_text: [{ text: { content: p.owner } }] },
      'Repo URL': { url: p.repo },
      'Tech Debt': { number: p.techDebt },
      'Business Value': { number: p.businessValue },
      'Needs Migration': { checkbox: p.platform === 'Base44' || p.platform === 'Bolt' },
      'Stars': { number: p.githubData?.stars || 0 },
      'Open Issues': { number: p.githubData?.openIssues || 0 },
      'Has README': { checkbox: p.auditChecks?.readme || false },
      'Has Tests': { checkbox: p.auditChecks?.tests || false },
      'Has CI': { checkbox: p.auditChecks?.ci || false },
      'Last Synced': { date: { start: new Date().toISOString().split('T')[0] } }
    };

    if (searchRes.results.length > 0) {
      // Update existing
      await this.helpers.httpRequest({
        method: 'PATCH',
        url: 'https://api.notion.com/v1/pages/' + searchRes.results[0].id,
        headers: {
          'Authorization': `Bearer ${$credentials.notionApi.apiKey}`,
          'Notion-Version': '2022-06-28',
          'Content-Type': 'application/json'
        },
        body: { properties }
      });
      results.push({ action: 'updated', name: p.name });
    } else {
      // Create new
      await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://api.notion.com/v1/pages',
        headers: {
          'Authorization': `Bearer ${$credentials.notionApi.apiKey}`,
          'Notion-Version': '2022-06-28',
          'Content-Type': 'application/json'
        },
        body: { parent: { database_id: dbId }, properties }
      });
      results.push({ action: 'created', name: p.name });
    }

    await new Promise(r => setTimeout(r, 350)); // Notion rate limit
  } catch (e) {
    results.push({ action: 'error', name: p.name, error: e.message });
  }
}

return [{ json: { notionSync: results, created: results.filter(r => r.action === 'created').length, updated: results.filter(r => r.action === 'updated').length } }];

